frappe.ui.form.on("Leave Application", {
    onload_post_render(frm) {
        const is_hr =
            frappe.session.user === "Administrator" ||
            ["HR User", "HR Manager", "System Manager"]
                .some(role => frappe.user.has_role(role));

        if (is_hr) return;

        const hr_only_types = [
            "Mateřská dovolená",
            "Otcovská dovolená",
            "Rodičovská dovolená",
            "Překážka na straně zaměstnavatele",
            "Jiná překážka"
        ];

        const field = frm.fields_dict.leave_type;

        const apply_filter = () => {
            const original = field.get_query;

            if (!original || original._verisoft_wrapped) {
                return;
            }

            const wrapped = function() {
                const result = original.call(this) || {};

                return {
                    ...result,
                    filters: [
                        ...(result.filters || []),
                        [
                            "leave_type_name",
                            "not in",
                            hr_only_types
                        ]
                    ]
                };
            };

            wrapped._verisoft_wrapped = true;
            field.get_query = wrapped;
        };

        // Apply filter whenever the user interacts with the field.
        field.$input
            .off(".verisoft_leave")
            .on(
                "mousedown.verisoft_leave focusin.verisoft_leave",
                apply_filter
            );

        apply_filter();
    }
});

frappe.ui.form.on('Employee Data Change Request', {
    onload(frm) {
        if (frm.is_new()) {
            frm.set_value('requested_by', frappe.session.user);
            frm.set_value('request_date', frappe.datetime.now_datetime());

            frappe.db.get_value(
                'Employee',
                { user_id: frappe.session.user },
                [
                    'name',
                    'cell_number',
                    'personal_email',
                    'date_of_birth',
                    'current_address'
                ]
            ).then(r => {
                if (!r.message || !r.message.name) {
                    frappe.msgprint(
                        'No Employee record is linked to the current user.'
                    );
                    return;
                }

                frm.set_value('employee', r.message.name);
                frm.set_value('current_mobile_number', r.message.cell_number);
                frm.set_value('current_personal_email', r.message.personal_email);
                frm.set_value('current_date_of_birth', r.message.date_of_birth);
                frm.set_value('current_address', r.message.current_address);
            });
        }
    }
});
